<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import Modal from 'ant-design-vue/es/modal'
import message from 'ant-design-vue/es/message'
import { Archive, BookOpen, FileText, FileUp, FolderOpen, Plus, RefreshCw, RotateCcw } from '@lucide/vue'
import { knowledgeApi } from '@/api/knowledge'
import AppShell from '@/components/AppShell.vue'
import PageHeader from '@/components/PageHeader.vue'
import StatusTag from '@/components/StatusTag.vue'
import { formatBytes, formatDate } from '@/utils/display'
import type { KnowledgeBase, KnowledgeDocument } from '@/types'

const route = useRoute(); const workspaceId = computed(() => String(route.params.workspaceId)); const knowledgeBases = ref<KnowledgeBase[]>([]); const documents = ref<KnowledgeDocument[]>([]); const selectedId = ref(''); const loading = ref(false); const docsLoading = ref(false); const creating = ref(false); const createLoading = ref(false); const createForm = ref({ name: '', description: '' }); const fileInput = ref<HTMLInputElement | null>(null); let pollTimer: number | null = null
const selected = computed(() => knowledgeBases.value.find((kb) => kb.id === selectedId.value) || null); const processing = computed(() => documents.value.some((doc) => ['PENDING', 'PARSING'].includes(doc.parseStatus)))
async function loadBases() { loading.value = true; try { knowledgeBases.value = await knowledgeApi.list(workspaceId.value); if (!knowledgeBases.value.some((kb) => kb.id === selectedId.value)) selectedId.value = knowledgeBases.value[0]?.id || ''; if (selectedId.value) await loadDocuments() } catch (error) { message.error(error instanceof Error ? error.message : '知识库加载失败') } finally { loading.value = false } }
async function loadDocuments() { if (!selectedId.value) { documents.value = []; stopPolling(); return }; docsLoading.value = true; try { documents.value = await knowledgeApi.documents(workspaceId.value, selectedId.value); if (processing.value) beginPolling(); else stopPolling() } catch (error) { message.error(error instanceof Error ? error.message : '文档加载失败') } finally { docsLoading.value = false } }
function chooseBase(id: string) { selectedId.value = id; void loadDocuments() }
async function createBase() { if (!createForm.value.name.trim()) { message.warning('请输入知识库名称'); return }; createLoading.value = true; try { const kb = await knowledgeApi.create(workspaceId.value, { name: createForm.value.name.trim(), description: createForm.value.description || undefined }); knowledgeBases.value.unshift(kb); selectedId.value = kb.id; creating.value = false; createForm.value = { name: '', description: '' }; await loadDocuments(); message.success('知识库已创建') } catch (error) { message.error(error instanceof Error ? error.message : '创建失败') } finally { createLoading.value = false } }
function startUpload() { if (!selected.value || selected.value.status !== 'ACTIVE') { message.warning('请先选择一个启用中的知识库'); return }; fileInput.value?.click() }
async function handleFile(event: Event) { const file = (event.target as HTMLInputElement).files?.[0]; (event.target as HTMLInputElement).value = ''; if (!file) return; const extension = file.name.split('.').pop()?.toLowerCase(); if (!extension || !['txt', 'md', 'pdf'].includes(extension)) { message.error('仅支持 .txt、.md 和 .pdf 文件'); return }; if (file.size > 5 * 1024 * 1024) { message.error('文件大小不能超过 5MB'); return }; try { const doc = await knowledgeApi.upload(workspaceId.value, selectedId.value, file); documents.value.unshift(doc); beginPolling(); message.success('文件已上传，正在解析') } catch (error) { message.error(error instanceof Error ? error.message : '上传失败') } }
async function reindex(doc: KnowledgeDocument) { try { const next = await knowledgeApi.reindex(workspaceId.value, selectedId.value, doc.id); Object.assign(doc, next); message.success('已重新提交索引') } catch (error) { message.error(error instanceof Error ? error.message : '重新索引失败') } }
async function disableBase(kb: KnowledgeBase) { Modal.confirm({ title: '停用知识库', content: `停用“${kb.name}”后，它不会再出现在新任务的选择列表中。`, okText: '确认停用', cancelText: '取消', okButtonProps: { danger: true }, async onOk() { try { const next = await knowledgeApi.disable(workspaceId.value, kb.id); Object.assign(kb, next); message.success('知识库已停用') } catch (error) { message.error(error instanceof Error ? error.message : '停用失败') } } }) }
function beginPolling() { if (pollTimer !== null || !processing.value) return; pollTimer = window.setInterval(() => void loadDocuments(), 5000) }
function stopPolling() { if (pollTimer !== null) window.clearInterval(pollTimer); pollTimer = null }
onMounted(async () => { await loadBases(); await nextTick(); beginPolling() }); onBeforeUnmount(stopPolling)
</script>

<template><AppShell><div class="page-content"><PageHeader eyebrow="KNOWLEDGE BASE" title="知识库" description="管理研究资料，让 Agent 在可信的上下文中工作。"><a-button @click="loadBases"><RefreshCw :size="15"/> 刷新</a-button><a-button type="primary" @click="creating = true"><Plus :size="16"/> 新建知识库</a-button></PageHeader><div class="knowledge-layout"><section class="soft-panel kb-list-panel"><div class="panel-heading"><div><h2>我的知识库</h2><p>{{ knowledgeBases.length }} 个空间内的资料集合</p></div><BookOpen :size="18" class="panel-icon"/></div><div v-if="knowledgeBases.length" class="kb-list"><button v-for="kb in knowledgeBases" :key="kb.id" class="kb-list-item" :class="{ active: selectedId === kb.id }" @click="chooseBase(kb.id)"><span class="kb-list-icon"><FolderOpen :size="17"/></span><span class="kb-list-copy"><strong>{{ kb.name }}</strong><small>{{ kb.docCount }} 份文档</small></span><StatusTag :status="kb.status === 'ACTIVE' ? 'INDEXED' : 'FAILED'"/></button></div><div v-else class="empty-state compact"><BookOpen :size="25"/><h3>还没有知识库</h3><p>创建一个资料集合开始沉淀。</p></div><button class="kb-add-link" @click="creating = true"><Plus :size="15"/> 创建知识库</button></section><section class="kb-doc-section"><div v-if="selected" class="document-toolbar"><div><h2>{{ selected.name }}</h2><p>{{ selected.description || '这个知识库还没有描述。' }}</p></div><div class="button-row"><input ref="fileInput" type="file" accept=".txt,.md,.pdf,application/pdf,text/plain,text/markdown" hidden @change="handleFile"/><a-button :disabled="selected.status !== 'ACTIVE'" type="primary" @click="startUpload"><FileUp :size="15"/> 上传文档</a-button><a-button v-if="selected.status === 'ACTIVE'" danger ghost @click="disableBase(selected)"><Archive :size="15"/> 停用</a-button></div></div><div v-if="selected" class="document-summary"><span><strong>{{ documents.length }}</strong> 份文档</span><span>支持 TXT、Markdown、PDF</span><span>单文件最大 5MB</span><span v-if="processing" class="processing-note"><span class="online-dot"/> 正在解析</span></div><a-table v-if="selected" :data-source="documents" :loading="docsLoading" row-key="id" :pagination="{ pageSize: 10, hideOnSinglePage: true }"><a-table-column key="fileName" title="文档" :width="310"><template #default="{ record }"><div class="document-name"><FileText :size="16"/><div><strong>{{ record.fileName }}</strong><span>{{ formatBytes(record.fileSize) }} · {{ formatDate(record.createdAt) }}</span></div></div></template></a-table-column><a-table-column key="parseStatus" title="解析状态" :width="150"><template #default="{ record }"><StatusTag :status="record.parseStatus"/><div v-if="record.errorMessage" class="error-subline">{{ record.errorMessage }}</div></template></a-table-column><a-table-column key="chunkCount" title="切片" :width="100"><template #default="{ record }"><span class="muted">{{ record.chunkCount || '—' }}</span></template></a-table-column><a-table-column key="actions" title="" :width="120"><template #default="{ record }"><a-button v-if="record.parseStatus === 'FAILED'" type="link" size="small" @click="reindex(record)"><RotateCcw :size="14"/> 重新索引</a-button></template></a-table-column><template #emptyText><div class="empty-state"><FolderOpen :size="28"/><h3>还没有文档</h3><p>上传 TXT、Markdown 或 PDF，开始构建你的研究上下文。</p></div></template></a-table><div v-else class="empty-state workspace-empty"><BookOpen :size="34"/><h3>选择一个知识库</h3><p>从左侧选择资料集合，查看文档解析状态。</p></div></section></div><Modal v-model:open="creating" title="新建知识库" :confirm-loading="createLoading" ok-text="创建" cancel-text="取消" @ok="createBase"><a-form layout="vertical" class="modal-form"><a-form-item label="名称" required><a-input v-model:value="createForm.name" maxlength="128" placeholder="例如：产品研究资料"/></a-form-item><a-form-item label="描述"><a-textarea v-model:value="createForm.description" :rows="3" maxlength="512" placeholder="可选，描述资料的范围和用途"/></a-form-item></a-form></Modal></div></AppShell></template>
